// === Tab: projection ===
// Perspective projection setup
const project3D = ([x, y, z], fov = 150) => {
	const scale = fov / (fov + z);
	return [x * scale, y * scale];
};

const transform3D = ([x, y, z], m) => [
	x * m[0][0] + y * m[0][1] + z * m[0][2],
	x * m[1][0] + y * m[1][1] + z * m[1][2],
	x * m[2][0] + y * m[2][1] + z * m[2][2]
];

const rotX = (a) => [
	[1, 0, 0],
	[0, Math.cos(a), -Math.sin(a)],
	[0, Math.sin(a), Math.cos(a)]
];

const rotY = (a) => [
	[Math.cos(a), 0, Math.sin(a)],
	[0, 1, 0],
	[-Math.sin(a), 0, Math.cos(a)]
];

const rotZ = (a) => [
	[Math.cos(a), -Math.sin(a), 0],
	[Math.sin(a), Math.cos(a), 0],
	[0, 0, 1]
];


const rotateX3D = (point, angle) => transform3D(point, rotX(angle));
const rotateY3D = (point, angle) => transform3D(point, rotY(angle));
const rotateZ3D = (point, angle) => transform3D(point, rotZ(angle));

